// Package stdlib provides Database ORM support for FV 2.0
package stdlib

import (
	"database/sql"
	"fmt"
	"strings"

	_ "github.com/mattn/go-sqlite3"
)

// Database represents a database connection pool
type Database struct {
	DB                 *sql.DB
	ConnectionString   string
	MaxConnections     int
	Timeout            int
	LastInsertID       int64
	RowsAffected       int64
	QueryTimeout       int
}

// Row represents a database row result
type Row struct {
	Values map[string]interface{}
}

// Result represents a query result
type Result struct {
	Rows           []*Row
	LastInsertID   int64
	RowsAffected   int64
	Error          error
}

// Query represents a database query builder
type Query struct {
	db              *Database
	selectCols      []string
	fromTable       string
	whereClauses    []string
	orderByClause   string
	limitClause     string
	offsetClause    string
	joinClauses     []string
	groupByClause   string
	havingClause    string
	distinct        bool
	params          []interface{}
}

// Transaction represents a database transaction
type Transaction struct {
	tx *sql.Tx
	db *Database
}

// NewDatabase creates a new database connection
func NewDatabase(connectionString string) (*Database, error) {
	db, err := sql.Open("sqlite3", connectionString)
	if err != nil {
		return nil, err
	}

	// Test connection
	if err := db.Ping(); err != nil {
		return nil, err
	}

	return &Database{
		DB:               db,
		ConnectionString: connectionString,
		MaxConnections:   10,
		Timeout:          5000,
		QueryTimeout:     30,
	}, nil
}

// Close closes the database connection
func (d *Database) Close() error {
	return d.DB.Close()
}

// Exec executes a statement without returning rows
func (d *Database) Exec(query string, args ...interface{}) (*Result, error) {
	result, err := d.DB.Exec(query, args...)
	if err != nil {
		return nil, err
	}

	lastID, _ := result.LastInsertId()
	rowsAffected, _ := result.RowsAffected()

	return &Result{
		LastInsertID: lastID,
		RowsAffected: rowsAffected,
		Error:        nil,
	}, nil
}

// Query executes a query that returns rows
func (d *Database) Query(query string, args ...interface{}) (*Result, error) {
	rows, err := d.DB.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	result := &Result{
		Rows: make([]*Row, 0),
	}

	columns, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(columns))
		valuePtrs := make([]interface{}, len(columns))

		for i := range columns {
			valuePtrs[i] = &values[i]
		}

		if err := rows.Scan(valuePtrs...); err != nil {
			return nil, err
		}

		row := &Row{
			Values: make(map[string]interface{}),
		}

		for i, col := range columns {
			val := values[i]
			if b, ok := val.([]byte); ok {
				row.Values[col] = string(b)
			} else {
				row.Values[col] = val
			}
		}

		result.Rows = append(result.Rows, row)
	}

	return result, nil
}

// QueryRow executes a query that returns a single row
func (d *Database) QueryRow(query string, args ...interface{}) (*Row, error) {
